import type { HTMLAttributes, ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './typography.module.scss'

/** Inline code fragment. */
export function Code({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return <code className={cx(styles.code, className)} {...props} />
}

/** Highlighted search match or emphasis. */
export function Highlight({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return <mark className={cx(styles.highlight, className)} {...props} />
}

const SIZES = {
  sm: styles.sizeSm,
  md: styles.sizeMd,
  lg: styles.sizeLg,
  xl: styles.sizeXl,
} as const

export interface HeadingProps extends HTMLAttributes<HTMLHeadingElement> {
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'
  size?: keyof typeof SIZES
  children: ReactNode
}

/** Semantic heading with a decoupled visual size. */
export function Heading({
  as: Tag = 'h2',
  size = 'md',
  className,
  ...props
}: HeadingProps) {
  return (
    <Tag className={cx(styles.heading, SIZES[size], className)} {...props} />
  )
}

@use 'styles' as vz;

.code {
  padding: 0.1em 0.35em;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xs');
  background: vz.color('muted');
  color: vz.color('foreground');
  font-family: SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.875em;
}

.highlight {
  padding: 0.05em 0.2em;
  border-radius: 3px;
  background: vz.color('warning', 0.28);
  color: vz.color('foreground');
}

.heading {
  margin: 0;
  color: vz.color('foreground');
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.15;
}

.size-sm {
  font-size: vz.font-size('lg');
}

.size-md {
  font-size: vz.font-size('2xl');
}

.size-lg {
  font-size: vz.font-size('3xl');
}

.size-xl {
  font-size: vz.font-size('4xl');
}
